class Solution:
    def reverseWords(self, s: str) -> str:
        result, index = '', 0
        while index < len(s):
            while index < len(s) and s[index] == ' ':
                index += 1
            start = index
            while index < len(s) and s[index] != ' ':
                index += 1
            if start < index:
                result = s[start:index] + (' ' + result if result else '')
        return result
